char* itoa(int value, char* str, int base) { if (base < 2 || base > 36) { *str = 0; return str; } char* ret = str; char* start = ret; if (value < 0) *(ret++) = '-'; char* end = ret; do { *(ret++) = "zyxwvutsrqponmlkjihgfedcba9876543210123456789"[value % base + 35]; } while (value /= base); *(ret--) = 0; while (end < ret) { char digit = *end; *(end++) = *(ret); *(ret--) = digit; } return start; }